    double w, x, y, z;
    double norm;
    adcs_quat_t out;

    if ((q == NULL) || (canonical == NULL)) {
        return ADCS_E_NULL;
    }

    w = q->w;
    x = q->x;
    y = q->y;
    z = q->z;

    if (!isfinite(w) || !isfinite(x) || !isfinite(y) || !isfinite(z)) {
        return ADCS_E_DEGENERATE;
    }

    norm = sqrt(w * w + x * x + y * y + z * z);

    if (norm <= ADCS_EPS_QUAT) {
        return ADCS_E_DEGENERATE;
    }

    out.w = w / norm;
    out.x = x / norm;
    out.y = y / norm;
    out.z = z / norm;

    if (out.w < 0.0) {
        out.w = -out.w;
        out.x = -out.x;
        out.y = -out.y;
        out.z = -out.z;
    } else if (out.w < ADCS_EPS_QUAT) {
        if (out.x < 0.0) {
            out.w = -out.w;
            out.x = -out.x;
            out.y = -out.y;
            out.z = -out.z;
        } else if (out.x < ADCS_EPS_QUAT) {
            if (out.y < 0.0) {
                out.w = -out.w;
                out.x = -out.x;
                out.y = -out.y;
                out.z = -out.z;
            } else if (out.y < ADCS_EPS_QUAT) {
                if (out.z < 0.0) {
                    out.w = -out.w;
                    out.x = -out.x;
                    out.y = -out.y;
                    out.z = -out.z;
                }
            }
        }
    }

    *canonical = out;
    return ADCS_OK;
}

