candidates.raw:
    if ((q == NULL) || (canonical == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(q->w)) || (!isfinite(q->x)) || (!isfinite(q->y)) || (!isfinite(q->z))) {
        return ADCS_E_NOT_FINITE;
    }

    double n = sqrt(q->w * q->w + q->x * q->x + q->y * q->y + q->z * q->z);

    if (n <= ADCS_EPS_QUAT) {
        *canonical = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    double inv_n = 1.0 / n;
    double w = q->w * inv_n;
    double x = q->x * inv_n;
    double y = q->y * inv_n;
    double z = q->z * inv_n;

    if (w > 0.0) {
        /* First nonzero is w, positive. OK. */
    } else if (w < 0.0) {
        /* First nonzero is w, negative. Flip. */
        w = -w;
        x = -x;
        y = -y;
        z = -z;
    } else {
        /* w is zero, check x */
        if (x > 0.0) {
            /* First nonzero is x, positive. OK. */
        } else if (x < 0.0) {
            /* First nonzero is x, negative. Flip. */
            w = -w;
            x = -x;
            y = -y;
            z = -z;
        } else {
            /* x is zero, check y */
            if (y > 0.0) {
                /* First nonzero is y, positive. OK. */
            } else if (y < 0.0) {
                /* First nonzero is y, negative. Flip. */
                w = -w;
                x = -x;
                y = -y;
                z = -z;
            } else {
                /* y is zero, check z */
                if (z < 0.0) {
                    /* First nonzero is z, negative. Flip. */
                    w = -w;
                    x = -x;
                    y = -y;
                    z = -z;
                }
                /* If z > 0, first nonzero is z, positive. OK. */
            }
        }
    }

    canonical->w = w;
    canonical->x = x;
    canonical->y = y;
    canonical->z = z;

    return ADCS_OK;
}

